-- Demo seed for Retool Database (Postgres).
-- Clearly fictional support data. All emails use the example.com domain.
-- As-of time for relative 'stuck' tickets: 2026-11-23 20:00:00+01 (Africa/Lagos).
-- Safe to re-run: drops and recreates the three demo tables.

BEGIN;

DROP TABLE IF EXISTS support_desk_ticket_events CASCADE;
DROP TABLE IF EXISTS support_desk_tickets CASCADE;
DROP TABLE IF EXISTS support_desk_customers CASCADE;

CREATE TABLE support_desk_customers (
  id INTEGER PRIMARY KEY,
  first_name TEXT NOT NULL,
  last_name TEXT NOT NULL,
  email TEXT NOT NULL UNIQUE,
  company TEXT NOT NULL,
  plan TEXT NOT NULL CHECK (plan IN ('free', 'starter', 'pro', 'enterprise')),
  created_at TIMESTAMPTZ NOT NULL
);

CREATE TABLE support_desk_tickets (
  id INTEGER PRIMARY KEY,
  ticket_number TEXT NOT NULL UNIQUE,
  customer_id INTEGER NOT NULL REFERENCES support_desk_customers(id),
  subject TEXT NOT NULL,
  body TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('open', 'in_progress', 'waiting_on_customer', 'resolved', 'escalated')),
  priority TEXT NOT NULL CHECK (priority IN ('low', 'medium', 'high', 'urgent')),
  channel TEXT NOT NULL CHECK (channel IN ('email', 'chat', 'phone')),
  assigned_to TEXT,
  created_at TIMESTAMPTZ NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL,
  first_response_at TIMESTAMPTZ,
  resolved_at TIMESTAMPTZ,
  escalated_at TIMESTAMPTZ
);

CREATE TABLE support_desk_ticket_events (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  ticket_id INTEGER NOT NULL REFERENCES support_desk_tickets(id),
  event_type TEXT NOT NULL,
  note TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX support_desk_tickets_status_idx ON support_desk_tickets (status);
CREATE INDEX support_desk_tickets_customer_idx ON support_desk_tickets (customer_id);
CREATE INDEX support_desk_tickets_updated_idx ON support_desk_tickets (updated_at);



SELECT setval(pg_get_serial_sequence('support_desk_ticket_events', 'id'), 1, false);

COMMIT;
